-- ============================================
-- 테스트 데이터 확장: 오프라인 판매, 반품, 맞춤피복, 체척권
-- 실행 전제: 001~004 마이그레이션 + 메인 seed.sql 완료
-- ============================================

DO $$
BEGIN
  -- 이미 실행됐으면 건너뜀
  IF EXISTS (SELECT 1 FROM orders WHERE id = 'b0200000-0000-0000-0000-000000000001') THEN
    RAISE NOTICE '확장 테스트 데이터가 이미 존재합니다. 건너뜁니다.';
    RETURN;
  END IF;

  -- 사용자 데이터가 없으면 건너뜀
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = 'd1000000-0000-0000-0000-000000000006') THEN
    RAISE NOTICE '사용자 데이터가 없습니다. 확장 테스트 데이터 생성을 건너뜁니다.';
    RETURN;
  END IF;

  -- ============================================
  -- 1. 오프라인 판매 완료 주문 10건 (제1판매소)
  -- users: u6~u15
  -- ============================================

  -- 오프라인 판매 주문 항목

  -- 오프라인 판매 포인트 차감

  UPDATE point_summary SET used_points = used_points + 45000  WHERE user_id = 'd1000000-0000-0000-0000-000000000006';
  UPDATE point_summary SET used_points = used_points + 85000  WHERE user_id = 'd1000000-0000-0000-0000-000000000007';
  UPDATE point_summary SET used_points = used_points + 70000  WHERE user_id = 'd1000000-0000-0000-0000-000000000008';
  UPDATE point_summary SET used_points = used_points + 35000  WHERE user_id = 'd1000000-0000-0000-0000-000000000009';
  UPDATE point_summary SET used_points = used_points + 45000  WHERE user_id = 'd1000000-0000-0000-0000-000000000010';
  UPDATE point_summary SET used_points = used_points + 80000  WHERE user_id = 'd1000000-0000-0000-0000-000000000011';
  UPDATE point_summary SET used_points = used_points + 120000 WHERE user_id = 'd1000000-0000-0000-0000-000000000012';
  UPDATE point_summary SET used_points = used_points + 45000  WHERE user_id = 'd1000000-0000-0000-0000-000000000013';
  UPDATE point_summary SET used_points = used_points + 55000  WHERE user_id = 'd1000000-0000-0000-0000-000000000014';
  UPDATE point_summary SET used_points = used_points + 90000  WHERE user_id = 'd1000000-0000-0000-0000-000000000015';

  -- ============================================
  -- 2. 오프라인 반품 주문 3건 (제3판매소)
  -- 주문은 delivered, 항목은 returned
  -- ============================================


  -- 반품: 구매차감 후 포인트 환불
  -- 반품은 차감/환불 상계 → point_summary 변동 없음

  -- ============================================
  -- 3. 맞춤피복 온라인 주문 5건 + 체척권 발행
  -- users: u19~u22, u21
  -- 맞춤피복 제품: f1000000-...000015 ~ 000000000019
  -- ============================================


  -- 맞춤피복 예약포인트 처리 (pending/confirmed 주문)
    -- 배송완료(주문3): 예약→차감
    ('d1000000-0000-0000-0000-000000000021', 'reserve',  220000, '온라인 구매 예약 (맞춤피복)', 'order', 'b0300000-0000-0000-0000-000000000003', 2026),
    ('d1000000-0000-0000-0000-000000000021', 'use',      220000, '배송 확정 차감',              'order', 'b0300000-0000-0000-0000-000000000003', 2026),
    ('d1000000-0000-0000-0000-000000000021', 'release',  220000, '배송 확정 예약해제',           'order', 'b0300000-0000-0000-0000-000000000003', 2026),
    -- 배송완료(주문5): 예약→차감 (u6는 이미 오프라인 45000 차감된 상태)
    ('d1000000-0000-0000-0000-000000000006', 'reserve',  200000, '온라인 구매 예약 (맞춤피복)', 'order', 'b0300000-0000-0000-0000-000000000005', 2026),
    ('d1000000-0000-0000-0000-000000000006', 'use',      200000, '배송 확정 차감',              'order', 'b0300000-0000-0000-0000-000000000005', 2026),
    ('d1000000-0000-0000-0000-000000000006', 'release',  200000, '배송 확정 예약해제',           'order', 'b0300000-0000-0000-0000-000000000005', 2026);

  UPDATE point_summary SET reserved_points = reserved_points + 180000 WHERE user_id = 'd1000000-0000-0000-0000-000000000019';
  UPDATE point_summary SET reserved_points = reserved_points + 200000 WHERE user_id = 'd1000000-0000-0000-0000-000000000020';
  UPDATE point_summary SET used_points     = used_points     + 220000 WHERE user_id = 'd1000000-0000-0000-0000-000000000021';
  UPDATE point_summary SET used_points     = used_points     + 200000 WHERE user_id = 'd1000000-0000-0000-0000-000000000006';

  -- ============================================
  -- 4. 체척권 데이터 (10건, 상태별 분산)
  -- ============================================
    -- issued (등록 대기): 3건
    ('bb000000-0000-0000-0000-000000000001', 'TK-2026-0001', 'bc010000-0000-0000-0000-000000000001', 'd1000000-0000-0000-0000-000000000019', 'f1000000-0000-0000-0000-000000000015', 180000, 'issued',           NULL, NULL, NULL),
    ('bb000000-0000-0000-0000-000000000002', 'TK-2026-0002', 'bc010000-0000-0000-0000-000000000002', 'd1000000-0000-0000-0000-000000000020', 'f1000000-0000-0000-0000-000000000016', 200000, 'issued',           NULL, NULL, NULL),
    ('bb000000-0000-0000-0000-000000000003', 'TK-2026-0003', NULL,                                   'd1000000-0000-0000-0000-000000000021', 'f1000000-0000-0000-0000-000000000017', 220000, 'issued',           NULL, NULL, NULL),
    -- registered (업체 등록 완료): 3건
    ('bb000000-0000-0000-0000-000000000004', 'TK-2026-0004', 'bc010000-0000-0000-0000-000000000003', 'd1000000-0000-0000-0000-000000000021', 'f1000000-0000-0000-0000-000000000017', 220000, 'registered',       'b1000000-0000-0000-0000-000000000001', now() - interval '15 days', NULL),
    ('bb000000-0000-0000-0000-000000000005', 'TK-2026-0005', 'bc010000-0000-0000-0000-000000000005', 'd1000000-0000-0000-0000-000000000006', 'f1000000-0000-0000-0000-000000000019', 200000, 'registered',       'b1000000-0000-0000-0000-000000000002', now() - interval '28 days', NULL),
    ('bb000000-0000-0000-0000-000000000006', 'TK-2026-0006', NULL,                                   'd1000000-0000-0000-0000-000000000007', 'f1000000-0000-0000-0000-000000000015', 180000, 'registered',       'b1000000-0000-0000-0000-000000000003', now() - interval '10 days', NULL),
    -- cancel_requested (취소 요청): 2건
    ('bb000000-0000-0000-0000-000000000007', 'TK-2026-0007', NULL,                                   'd1000000-0000-0000-0000-000000000008', 'f1000000-0000-0000-0000-000000000016', 200000, 'cancel_requested',  NULL, NULL, NULL),
    ('bb000000-0000-0000-0000-000000000008', 'TK-2026-0008', NULL,                                   'd1000000-0000-0000-0000-000000000009', 'f1000000-0000-0000-0000-000000000018', 180000, 'cancel_requested',  NULL, NULL, NULL),
    -- cancelled (취소 완료): 2건
    ('bb000000-0000-0000-0000-000000000009', 'TK-2026-0009', 'bc010000-0000-0000-0000-000000000004', 'd1000000-0000-0000-0000-000000000022', 'f1000000-0000-0000-0000-000000000018', 180000, 'cancelled',        NULL, NULL, now() - interval '20 days'),
    ('bb000000-0000-0000-0000-000000000010', 'TK-2026-0010', NULL,                                   'd1000000-0000-0000-0000-000000000010', 'f1000000-0000-0000-0000-000000000015', 180000, 'cancelled',        NULL, NULL, now() - interval '5 days');

  RAISE NOTICE '확장 테스트 데이터 생성 완료: 오프라인주문 13건, 맞춤피복주문 5건, 체척권 10건';
END $$;
